FULL SOURCE (global rail: a deleted probe is a lead only with its source inline):
```ts
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os"; import { join } from "node:path";
import { SqliteEventStore } from "@moe/store"; import { expect, it } from "vitest";
import { createDurableSchedule } from "../orchestrator/durable-schedule.js";
import type { ScheduleTimer } from "../orchestrator/durable-schedule.js";
const PROJECT = "step1-probe";
const timer: ScheduleTimer = { set: () => Symbol("h"), clear: () => {} };
it("DEFECT: a boot re-registration with no interval overwrites the stored non-default value", () => {
  const root = mkdtempSync(join(tmpdir(), "moe-step1-"));
  const store = SqliteEventStore.openForProject(join(root, "store.db"), PROJECT);
  const read = () => store.readEvents(`durable-schedule/${PROJECT}`)
    .map((e) => JSON.parse(new TextDecoder().decode(e.payload)) as { id: string; intervalMs: number });
  try {
    const first = createDurableSchedule({ store, projectId: PROJECT, timer });
    expect(first.register("monitoring/health-probes", () => {}, 30_000)).toEqual({ ok: true });
    expect(read().at(-1)).toEqual({ id: "monitoring/health-probes", intervalMs: 30_000 });
    first.release();
    const second = createDurableSchedule({ store, projectId: PROJECT, timer,
      resolve: (id) => id === "monitoring/health-probes" ? () => {} : null });
    try {
      second.register("monitoring/health-probes", () => {});
      expect(read().at(-1)).toEqual({ id: "monitoring/health-probes", intervalMs: 30_000 });
    } finally { second.release(); }
  } finally { store.close(); rmSync(root, { recursive: true, force: true }); }
});
```
